// Фиксированный тестовый запрос для сквозной проверки пути embeddings → Qdrant → hits.
// Вход (ответ Qdrant info) игнорируем — отчёт прочитает его по имени ноды.
return [{ json: { query: 'требование', topK: 3, threshold: 0 } }];

// Сводим два сигнала: прямой ответ Qdrant о коллекции + результат сквозного поиска через wf_rag.
const q = $('[ragHealth] Qdrant Collection Info').first().json || {};
const qResult = q.result || null;
const qdrantReachable = !!qResult && !q.error;
const pointsCount = qResult && typeof qResult.points_count === 'number' ? qResult.points_count : null;
const indexedVectors = qResult && typeof qResult.indexed_vectors_count === 'number' ? qResult.indexed_vectors_count : null;
const collectionStatus = qResult ? (qResult.status || null) : null;

// Выход wf_rag в режиме поиска: { _idx, query, hits: [...], extra }.
const rag = $input.first().json || {};
const hits = Array.isArray(rag.hits) ? rag.hits : [];
const searchOk = Array.isArray(rag.hits);
const topScore = hits.length ? hits[0].score : null;

let status = 'down';
if (qdrantReachable) {
  status = (pointsCount && pointsCount > 0 && hits.length > 0) ? 'ok' : 'degraded';
}

return [{
  json: {
    status,
    qdrant: {
      reachable: qdrantReachable,
      collection: 'docs_chunks',
      collection_status: collectionStatus,
      points_count: pointsCount,
      indexed_vectors_count: indexedVectors,
    },
    search: {
      ok: searchOk,
      query: rag.query || 'требование',
      hits: hits.length,
      top_score: topScore,
    },
  },
}];
